# Writes the hedra command files of the peg-drop workshop: board.txt (the peg board: felt, frame, 34
# brass pegs, the cup row and the cabinet), wall.txt (the workshop wall: striped paper, wainscot, a
# shelf of jars, lamps, a clock face), gear_big.txt / gear_small.txt, pendulum.txt, coin.txt, hand.txt,
# marker.txt, spark.txt. Run from models/env: /usr/bin/python3 make_env.py.
# hedra: up Z, front -Y (the camera side). The game's plane is hedra y = 0 (glTF z = 0): coins, the
# pendulum's bob and the pegs' heads meet there; the felt sits behind it (hedra y +0.2).
# Colours are exact Pear36 steps (sRGB 0..1). The layout numbers are shared with scene/game.as.
import math, random

HEX = {"felt": "3d6e70", "feltdark": "323e4f", "wood": "964253", "wooddark": "57294b", "brass": "f2a65e",
       "brassmid": "ba6156", "brassdark": "8c3f5d", "gold": "ffe478", "goldrim": "f2a65e", "copper": "eb564b",
       "jewel": "4da6ff", "steel": "7e7e8f", "steellite": "c2c2d1", "plum": "5a265e", "plumdark": "422445",
       "lamp": "ffe478", "glass": "4b5bab", "cream": "ffffeb", "bulb": "80366b", "pink": "ff6b97", "teal": "3ca370"}
def rgb(h):
    return " ".join(f"{int(h[i:i + 2], 16) / 255:.3f}" for i in (0, 2, 4))
def mat(name, col, emit=False):
    s = f"material new {name} --base-color {rgb(HEX[col])} --no-slot"
    return s + (f" --emission {rgb(HEX[col])}" if emit else "")
def box(name, x0, x1, y0, y1, z0, z1, m):
    """an axis-aligned box in hedra coordinates (y: depth, +y away from the camera; z: up)"""
    return [f"add mesh cube --name {name} --size 1 --location {(x0 + x1) / 2:.4f} {(y0 + y1) / 2:.4f} {(z0 + z1) / 2:.4f}",
            f"scale {x1 - x0:.4f} {y1 - y0:.4f} {z1 - z0:.4f}", "apply --scale", f"material assign {m}"]
def disc(name, x, y, z, r, depth, n, m, spin=0.0):
    """a cylinder whose axis looks at the camera (hedra Y)"""
    return [f"add mesh cylinder --name {name} --vertices {n} --radius {r:.4f} --depth {depth:.4f} "
            f"--location {x:.4f} {y:.4f} {z:.4f} --rotation 90 {spin:.2f} 0", f"material assign {m}"]
def join(names, keep):
    return ["select " + " ".join(names), f"active {keep}", "join"]
def write(fn, lines):
    open(fn, "w").write("\n".join(lines) + "\n")

# ---------------------------------------------------------------- layout (glTF metres, shared with game.as)
BOARD_X = 4.0                                   # inner half width
ROWS = [5.5 - 0.6 * k for k in range(7)]        # peg rows (y)
PIVOT = (0.0, 4.15); ARM = 1.85; SWING = 36.0   # the pendulum
BOB_R = 0.36; PEG_R = 0.09
DIVIDERS = [-2.85, -1.75, -0.6, 0.6, 1.75, 2.85]
DIV_TOP = 0.85

def pegs():
    out = []
    for k, y in enumerate(ROWS):
        xs = [-3.325 + 0.95 * i for i in range(8)] if k % 2 == 0 else [-2.85 + 0.95 * i for i in range(7)]
        for x in xs:
            dy = PIVOT[1] - y
            if 0 < dy and abs(x) < dy * math.tan(math.radians(SWING)) + 0.3:
                continue                                   # the rod sweeps there
            near = min(math.hypot(x - ARM * math.sin(math.radians(a)), y - (PIVOT[1] - ARM * math.cos(math.radians(a))))
                       for a in range(-36, 37, 2))
            if near < 0.75:
                continue                                   # the bob sweeps there
            if math.hypot(x - PIVOT[0], y - PIVOT[1]) < 0.62:
                continue
            out.append((x, y))
    return out

if __name__ == "__main__":
    P = pegs()
    open("pegs.txt", "w").write("\n".join(f"{x:.2f} {y:.2f}" for x, y in P) + "\n")

    # ------------------------------------------------------------ board
    b = ["# The peg board: teal felt between two wooden posts, brass pegs (generated by make_env.py),",
         "# the cup row (brass dividers, copper lips with dark bulbs, the middle cup's lip blue), the cabinet.",
         "new", mat("Felt", "felt"), mat("FeltDark", "feltdark"), mat("Wood", "wood"), mat("WoodDark", "wooddark"),
         mat("Brass", "brass"), mat("BrassDark", "brassdark"), mat("Copper", "copper"), mat("Jewel", "jewel"),
         mat("Bulb", "bulb")]
    # felt panel (its front at hedra y 0.2), a darker felt band behind the cups
    b += box("Felt", -BOARD_X, BOARD_X, 0.2, 0.32, 0.9, 6.62, "Felt")
    b += box("FeltLow", -BOARD_X, BOARD_X, 0.2, 0.32, -0.05, 0.9, "FeltDark")
    # posts and their brass caps
    for s, nm in ((-1, "L"), (1, "R")):
        x0, x1 = (-4.45, -4.0) if s < 0 else (4.0, 4.45)
        b += box("Post" + nm, x0, x1, -0.4, 0.34, -0.25, 6.95, "Wood")
        b += box("Cap" + nm, x0 - 0.06, x1 + 0.06, -0.46, 0.38, 6.95, 7.1, "Brass")
        b += ["add mesh ico-sphere --name Knob" + nm + f" --subdivisions 1 --radius 0.2 --location {(x0 + x1) / 2:.3f} -0.05 7.27",
              "material assign Brass"]
    # the rail the dropper rides on: a brass bar along the felt's top
    b += box("Rail", -BOARD_X, BOARD_X, -0.05, 0.2, 6.5, 6.66, "Brass")
    # pegs: a pin from the felt to the coin plane, a round brass head
    names = []
    for i, (x, y) in enumerate(P):
        b += [f"add mesh cylinder --name Pin{i} --vertices 6 --radius 0.075 --depth 0.24 --location {x:.3f} 0.08 {y:.3f} --rotation 90 0 0",
              "material assign BrassDark"]
        b += disc(f"Head{i}", x, -0.06, y, PEG_R + 0.02, 0.09, 8, "Brass", 22.5)
        names += [f"Pin{i}", f"Head{i}"]
    b += join(names, "Pin0") + ["rename Pin0 Pegs"]
    # the pendulum's pivot plate on the felt (the hub itself is part of the pendulum)
    b += disc("Plate", PIVOT[0], 0.15, PIVOT[1], 0.32, 0.1, 8, "BrassDark", 22.5)
    # the cup row: a wooden tray, brass dividers with round tops, copper lips
    b += box("Tray", -BOARD_X, BOARD_X, -0.42, 0.25, -0.22, 0.0, "Wood")
    dn = []
    for i, x in enumerate(DIVIDERS):
        b += box(f"Div{i}", x - 0.06, x + 0.06, -0.38, 0.22, 0.0, DIV_TOP, "Brass")
        b += disc(f"DivTop{i}", x, -0.08, DIV_TOP, 0.09, 0.6, 8, "Brass", 22.5)
        dn += [f"Div{i}", f"DivTop{i}"]
    b += join(dn, "Div0") + ["rename Div0 Dividers"]
    edges = [-BOARD_X] + DIVIDERS + [BOARD_X]
    for i in range(7):
        x0, x1 = edges[i] + 0.06, edges[i + 1] - 0.06
        b += box(f"Lip{i}", x0, x1, -0.42, -0.3, 0.0, 0.3, "Jewel" if i == 3 else "Copper")
        b += box(f"Bulb{i}", (x0 + x1) / 2 - 0.1, (x0 + x1) / 2 + 0.1, -0.48, -0.4, 0.06, 0.24, "Bulb")
    # the cabinet under the board
    b += box("Cabinet", -4.5, 4.5, -0.45, 0.4, -1.6, -0.22, "WoodDark")
    b += box("Top", -4.6, 4.6, -0.52, 0.42, -0.34, -0.22, "Wood")
    for i, x in enumerate((-2.2, 2.2)):
        b += box(f"Drawer{i}", x - 1.6, x + 1.6, -0.55, -0.45, -1.2, -0.5, "Wood")
        b += disc(f"Pull{i}", x, -0.62, -0.85, 0.11, 0.14, 8, "Brass", 22.5)
    b += ["select all", "shade flat", "export board.glb"]
    write("board.txt", b)

    # ------------------------------------------------------------ wall
    rnd = random.Random(5)
    w = ["# The workshop wall behind the board (hedra y 1.6): plum striped paper, a wooden wainscot, a shelf",
         "# of jars on the left, a clock face on the right (its hand a game bone), two hanging lamps (unlit bulbs). make_env.py.",
         "new", mat("Paper", "plum"), mat("PaperDark", "plumdark"), mat("Wood", "wood"), mat("WoodDark", "wooddark"),
         mat("Brass", "brass"), mat("Glass", "glass"), mat("Jewel", "jewel"), mat("Teal", "teal"), mat("Pink", "pink"),
         mat("Cream", "steellite"), mat("Lamp", "lamp", True), mat("Gold", "gold")]
    sn = []
    for i in range(30):
        x0 = -7.5 + i * 0.5
        w += box(f"S{i}", x0, x0 + 0.5, 1.6, 1.7, 1.0, 9.0, "Paper" if i % 2 == 0 else "PaperDark")
        sn.append(f"S{i}")
    w += join(sn, "S0") + ["rename S0 Paper"]
    w += box("Wainscot", -7.5, 7.5, 1.45, 1.6, -1.6, 1.0, "WoodDark")
    w += box("Rail", -7.5, 7.5, 1.35, 1.5, 0.95, 1.12, "Wood")
    # left: a shelf with jars of coins and gems
    w += box("Shelf", -7.2, -4.7, 0.9, 1.45, 1.9, 2.02, "Wood")
    for i, (x, h, m) in enumerate(((-6.75, 0.62, "Glass"), (-6.0, 0.48, "Teal"), (-5.3, 0.7, "Glass"))):
        w += box(f"Jar{i}", x - 0.26, x + 0.26, 1.0, 1.4, 2.02, 2.02 + h, m)
        w += box(f"Lid{i}", x - 0.29, x + 0.29, 0.97, 1.43, 2.02 + h, 2.1 + h, "Brass")
        w += box(f"Fill{i}", x - 0.2, x + 0.2, 0.96, 1.0, 2.08, 2.02 + h * 0.6, "Gold" if i != 1 else "Pink")
    # right: a clock face (its hand is a game bone)
    w += disc("ClockRim", 5.75, 1.3, 2.25, 0.74, 0.16, 12, "Wood", 15)
    w += disc("ClockFace", 5.75, 1.12, 2.25, 0.6, 0.12, 12, "Cream", 15)
    w += disc("ClockPin", 5.75, 0.98, 2.25, 0.09, 0.14, 8, "Brass", 22.5)
    # hanging lamps at the top corners: a cord, a brass shade, an unlit bulb
    for i, x in enumerate((-5.6, 5.6)):
        w += box(f"Cord{i}", x - 0.04, x + 0.04, 0.6, 0.68, 7.6, 9.0, "WoodDark")
        w += [f"add mesh cone --name Shade{i} --vertices 8 --radius1 0.42 --radius2 0.14 --depth 0.32 --location {x} 0.64 7.5 --rotation 0 0 22.5",
              "material assign Brass"]
        w += [f"add mesh ico-sphere --name Bulb{i} --subdivisions 1 --radius 0.17 --location {x} 0.64 7.28", "material assign Lamp"]
    w += ["select all", "shade flat", "export wall.glb"]
    write("wall.txt", w)

    # ------------------------------------------------------------ gears (game bones: they turn)
    def gear(fn, r, teeth, depth, m_body, m_hub, title):
        g = [f"# {title} Generated by make_env.py.", "new", mat("Body", m_body), mat("Hub", m_hub)]
        g += disc("Ring", 0, 0, 0, r * 0.84, depth, teeth * 2, "Body", 180.0 / (teeth * 2))
        tn = []
        tw = 2 * math.pi * r * 0.84 / teeth * 0.5
        for i in range(teeth):
            a = 360.0 * i / teeth
            ca, sa = math.cos(math.radians(a)), math.sin(math.radians(a))
            g += [f"add mesh cube --name T{i} --size 1 --location {r * 0.92 * ca:.4f} 0 {r * 0.92 * sa:.4f}",
                  f"scale {r * 0.2:.4f} {depth:.4f} {tw:.4f}", "apply --scale", f"set rotation 0 {-a:.2f} 0", "apply --rotation",
                  "material assign Body"]
            tn.append(f"T{i}")
        g += join(["Ring"] + tn, "Ring")
        # a raised hub and four spokes standing proud of the ring, darker
        g += disc("Hub", 0, -0.08, 0, r * 0.26, depth + 0.16, 8, "Hub", 22.5)
        for i in range(4):
            g += [f"add mesh cube --name Sp{i} --size 1 --location 0 -0.05 0", f"scale {r * 1.42:.4f} {depth + 0.1:.4f} {max(0.12, r * 0.14):.4f}",
                  "apply --scale", f"set rotation 0 {-45 * i:.1f} 0", "apply --rotation", "material assign Hub"]
        g += ["select all", "shade flat", f"export {fn}.glb"]
        write(fn + ".txt", g)
    gear("gear_big", 1.25, 14, 0.18, "brassmid", "brassdark", "A big brass gear on the wall, r 1.25, 14 teeth, origin at its axle.")
    gear("gear_small", 0.7, 9, 0.18, "brassmid", "brassdark", "A small brass gear, r 0.7, 9 teeth, origin at its axle.")

    # ------------------------------------------------------------ pendulum (origin at the pivot)
    write("pendulum.txt", ["# The pendulum: a hub at the pivot, a rod behind the coin plane, a brass bob in it (r 0.36).",
        "# Origin at the pivot; the game swings it (roll). Generated by make_env.py.",
        "new", mat("Rod", "brassdark"), mat("Bob", "brass"), mat("Hub", "copper"), mat("Face", "gold"),
        *box("Rod", -0.06, 0.06, 0.06, 0.16, -ARM, 0.0, "Rod"),
        *disc("Hub", 0, -0.02, 0, 0.2, 0.22, 8, "Hub", 22.5),
        *disc("Bob", 0, 0, -ARM, BOB_R, 0.18, 12, "Bob", 15),
        *disc("Boss", 0, -0.13, -ARM, 0.17, 0.1, 8, "Face", 22.5),
        "select all", "shade flat", "export pendulum.glb"])

    # ------------------------------------------------------------ coin (origin at its centre), the clock hand, marker, spark
    write("coin.txt", ["# A gold coin, r 0.22, 0.09 thick, its face to the camera; the rim a step darker.",
        "# Origin at its centre. Generated by make_env.py.",
        "new", mat("Face", "gold"), mat("Rim", "goldrim"),
        *disc("Coin", 0, 0, 0, 0.22, 0.09, 12, "Face", 15),
        "active Coin", "mode edit", 'select face where "abs(normal.z) < 0.5"', "material assign Rim", "mode object",
        "shade flat", "export coin.glb"])
    write("hand.txt", ["# The clock's hand: a dark bar from the centre, origin at the centre (the game turns it).",
        "# Generated by make_env.py.", "new", mat("Hand", "wooddark"),
        *box("Hand", -0.05, 0.05, -0.08, 0.0, -0.06, 0.48, "Hand"), "shade flat", "export hand.glb"])
    write("marker.txt", ["# The lit bulb over the doubled cup: an unlit diamond, origin at its centre. make_env.py.",
        "new", mat("Lamp", "lamp", True),
        "add mesh cone --name Up --vertices 4 --radius1 0.17 --radius2 0 --depth 0.18 --location 0 0 0.09", "material assign Lamp",
        "add mesh cone --name Down --vertices 4 --radius1 0.17 --radius2 0 --depth 0.18 --location 0 0 -0.09 --rotation 180 0 0",
        "material assign Lamp", "select Up Down", "active Up", "join", "shade flat", "export marker.glb"])
    write("spark.txt", ["# A spark: a tiny unlit cube (one or two art pixels). Generated by make_env.py.",
        "new", mat("Spark", "cream", True), "add mesh cube --name Spark --size 0.1", "material assign Spark", "export spark.glb"])
